sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Inter", sans-serif;
  background-color: #0e0e0e;
  color: #fff;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 50px 20px;
}

.container {
  max-width: 1200px;
  text-align: center;
}

h1 {
  font-size: 2rem;
  margin-bottom: 40px;
  color: #e3e3e3;
}

.plans {
  display: flex;
  justify-content: space-between;
  align-items: stretch;
  gap: 25px;
  flex-wrap: nowrap;  /* Prevent wrapping */
  overflow-x: auto;   /* Allow horizontal scroll if screen too small */
  padding-bottom: 10px;
}

.card {
  background-color: #1a1a1a;
  border-radius: 15px;
  padding: 25px;
  text-align: left;
  flex: 1 1 30%; /* ensures 3 cards in a row evenly */
  min-width: 300px;
  max-width: 350px;
  transition: transform 0.2s ease, box-shadow 0.3s ease;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.card:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 20px rgba(255, 255, 255, 0.1);
}

.card h2 {
  font-size: 1.4rem;
  margin-bottom: 10px;
}

.price {
  font-size: 1.6rem;
  font-weight: 600;
  margin-bottom: 5px;
}

.price span {
  font-size: 0.8rem;
  color: #bbb;
  display: block;
  margin-top: 3px;
}

button {
  background-color: #fff;
  color: #000;
  border: none;
  border-radius: 25px;
  padding: 10px;
  font-weight: 600;
  cursor: pointer;
  margin-top: 15px;
  transition: background-color 0.3s ease;
}

button:hover {
  background-color: #6c63ff;
  color: #fff;
}

ul {
  list-style: none;
  font-size: 0.9rem;
  margin-bottom: 10px;
}

ul li {
  margin: 8px 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

ul li::before {
  content: "★";
  color: #ffffff;
  font-size: 0.8rem;
}
